// Package proxy exposes StaticSites and container ports through a single
// dzjjy-owned listener using unguessable token paths.
//
// A site configured with spec.exposure.token is served at
// /_dzjjy/<token>/... instead of its raw port. The token is the only thing
// standing between the public internet and the site content, so it is always
// generated by the platform with cryptographic randomness unless the operator
// pins one explicitly.
package proxy

import (
	"crypto/rand"
	"encoding/base64"
	"fmt"
	"net"
	"net/http"
	"strings"
	"sync"
	"time"
)

// TokenPrefix is the URL path prefix reserved for exposed apps. It carries no
// secret: the per-app token that follows it is generated at runtime.
const TokenPrefix = "/_dzjjy/" // #nosec G101 -- URL path prefix, not a credential

// Upstream is a running target the proxy forwards traffic to.
type Upstream interface {
	// HostPort returns the address traffic should be forwarded to.
	HostPort() string
	// Serve handles a request whose path has already had the token prefix
	// stripped.
	Serve(http.ResponseWriter, *http.Request)
}

// Target is an upstream plus the metadata needed to route and resume it.
type Target struct {
	AppName    string
	Generation uint64
	Upstream   Upstream
}

// Resumer restarts a suspended target before traffic is proxied to it. It
// returns nil once the target is serving again.
type Resumer func(appName string, generation uint64) error

// AccessTracker is notified whenever a request reaches a live upstream so the
// caller can reset the idle window.
type AccessTracker func(appName string, generation uint64)

// Proxy routes token paths to their upstream targets.
type Proxy struct {
	mu       sync.RWMutex
	targets  map[string]Target
	server   *http.Server
	listener net.Listener
	once     sync.Once
	resume   Resumer
	touch    AccessTracker
}

// NewToken returns a cryptographically random, URL-safe access token.
func NewToken() (string, error) {
	buf := make([]byte, 24)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("failed to generate access token: %w", err)
	}
	return base64.RawURLEncoding.EncodeToString(buf), nil
}

// Start binds the proxy listener and begins serving.
func Start(bindAddress string, port int, resume Resumer, touch AccessTracker) (*Proxy, error) {
	if port < 0 || port > 65535 {
		return nil, fmt.Errorf("port must be between 0 and 65535")
	}
	listener, err := net.Listen("tcp", net.JoinHostPort(bindAddress, fmt.Sprint(port)))
	if err != nil {
		return nil, fmt.Errorf("failed to bind proxy port: %w", err)
	}
	p := &Proxy{
		targets:  make(map[string]Target),
		listener: listener,
		resume:   resume,
		touch:    touch,
	}
	p.server = &http.Server{
		Handler:           p,
		ReadHeaderTimeout: 10 * time.Second,
	}
	go func() { _ = p.server.Serve(listener) }()
	return p, nil
}

// Port returns the bound port.
func (p *Proxy) Port() int {
	return p.listener.Addr().(*net.TCPAddr).Port
}

// Register publishes a target under a token, replacing any previous target for
// the same app.
func (p *Proxy) Register(token string, target Target) error {
	if !validToken(token) {
		return fmt.Errorf("invalid access token")
	}
	p.mu.Lock()
	p.targets[token] = target
	p.mu.Unlock()
	return nil
}

// Unregister removes the target for a token.
func (p *Proxy) Unregister(token string) {
	p.mu.Lock()
	delete(p.targets, token)
	p.mu.Unlock()
}

// Lookup returns the target registered for a token.
func (p *Proxy) Lookup(token string) (Target, bool) {
	p.mu.RLock()
	defer p.mu.RUnlock()
	target, ok := p.targets[token]
	return target, ok
}

// Tokens lists the registered tokens for an app.
func (p *Proxy) Tokens(appName string) []string {
	p.mu.RLock()
	defer p.mu.RUnlock()
	var tokens []string
	for token, target := range p.targets {
		if target.AppName == appName {
			tokens = append(tokens, token)
		}
	}
	return tokens
}

// Close shuts the proxy listener down.
func (p *Proxy) Close() error {
	var err error
	p.once.Do(func() { err = p.server.Close() })
	return err
}

func (p *Proxy) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if !strings.HasPrefix(r.URL.Path, TokenPrefix) {
		http.NotFound(w, r)
		return
	}
	remainder := strings.TrimPrefix(r.URL.Path, TokenPrefix)
	token, rest, found := strings.Cut(remainder, "/")
	if !found {
		rest = ""
	}
	if !validToken(token) {
		http.NotFound(w, r)
		return
	}
	target, ok := p.Lookup(token)
	if !ok {
		http.NotFound(w, r)
		return
	}
	if target.Upstream == nil {
		http.Error(w, "app unavailable", http.StatusServiceUnavailable)
		return
	}
	if p.resume != nil {
		if err := p.resume(target.AppName, target.Generation); err != nil {
			http.Error(w, "app unavailable", http.StatusServiceUnavailable)
			return
		}
	}
	if p.touch != nil {
		p.touch(target.AppName, target.Generation)
	}
	rewritten := r.Clone(r.Context())
	rewritten.URL.Path = "/" + rest
	if rewritten.URL.RawPath != "" {
		rewritten.URL.RawPath = "/" + rest
	}
	target.Upstream.Serve(w, rewritten)
}

func validToken(token string) bool {
	if len(token) < 16 || len(token) > 128 {
		return false
	}
	for _, ch := range token {
		isLower := ch >= 'a' && ch <= 'z'
		isUpper := ch >= 'A' && ch <= 'Z'
		isDigit := ch >= '0' && ch <= '9'
		if !isLower && !isUpper && !isDigit && ch != '-' && ch != '_' {
			return false
		}
	}
	return true
}
